function shopForm(list){let fs=[x=>field('Item','title','text','','required'),x=>area('Observação','notes','')];if(list==='need')fs.push(x=>select('Prioridade','priority',['Baixa','Média','Alta'],'Média'));if(list==='wish')fs.push(x=>field('Valor estimado (R$)','amount','number','','min="0" step="0.01"'),x=>field('Link opcional','url','url',''));addRecord('shopping','Item',fs,{list,done:false})}
function catProfile(cat){let p=rec('cats').find(r=>r.kind==='Perfil'&&r.title===cat);openForm('Perfil · '+cat,[x=>field('Data de nascimento','birth','date',p?.birth||''),x=>field('Peso (kg)','weight','number',p?.weight||'','min="0" step="0.1"'),x=>area('Observações','notes',p?.notes||'')],{},o=>{if(p)Object.assign(p,o);else rec('cats').push({id:uid(),kind:'Perfil',title:cat,...o});save();render()})}
function setPin(){openForm('PIN da Terapia',[x=>field('PIN de 4 a 6 dígitos','pin','password','','required pattern="[0-9]{4,6}" inputmode="numeric" maxlength="6"'),x=>field('Confirmar PIN','confirm','password','','required pattern="[0-9]{4,6}" maxlength="6')],{},o=>{if(o.pin!==o.confirm){toast('Os PINs não coincidem.');return}data.therapyPin=o.pin;data.therapyUnlocked=true;save();render()})}
function exportBackup(){let blob=new Blob([JSON.stringify({app:'Petala',version:1,exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`petala-backup-${today()}.json`;a.click();URL.revokeObjectURL(a.href)}
function importBackup(e){let f=e.target.files[0];if(!f)return;let reader=new FileReader();reader.onload=()=>{try{let obj=JSON.parse(reader.result);let incoming=obj.data||obj;if(!incoming.records||typeof incoming.records!=='object')throw Error('Formato inválido');if(confirm('Importar substituirá os dados atuais deste aparelho. Faça um backup antes. Continuar?')){data=Object.assign(emptyData(),incoming);save();go('today');toast('Backup restaurado com sucesso.')}}catch(err){alert('Não foi possível importar: arquivo JSON inválido ou incompatível.')}e.target.value=''};reader.readAsText(f)}
async function requestNotifications(){if(window.Capacitor?.isNativePlatform?.()){try{await Capacitor.Plugins.LocalNotifications.requestPermissions();toast('Solicitação de permissão enviada. Confira as configurações do Android.')}catch(e){toast('Abra as permissões de notificações nas configurações do Android.')}return}if(!('Notification'in window)){alert('Este navegador não oferece notificações. No Android, instale o Pétala pela opção Adicionar à tela inicial ou use o APK.');return}let p=await Notification.requestPermission();toast(p==='granted'?'Permissão de notificações concedida.':'Permissão não concedida.')}
async function notify(title,body){if(window.Capacitor?.isNativePlatform?.()){try{await Capacitor.Plugins.LocalNotifications.schedule({notifications:[{id:Math.floor(Math.random()*2000000000),title,body,schedule:{at:new Date(Date.now()+1500)}}]});return}catch(e){}}if('Notification'in window&&Notification.permission==='granted')new Notification(title,{body});else toast(body)}
async function scheduleAll(){if(!window.Capacitor?.isNativePlatform?.())return;let list=[];modules.forEach(m=>rec(m.id).forEach(r=>{if(r.reminderEnabled===false)return;let d=r.remindDate||r.nextDate;if(!d||!r.remindTime)return;let at=new Date(`${d}T${r.remindTime}:00`);if(at>Date.now())list.push({id:hashId(m.id+r.id),title:r.title||r.kind||'Lembrete Pétala',body:`${name(m.id)} · ${r.notes||'Seu lembrete chegou.'}`,schedule:{at},extra:{module:m.id,record:r.id}})}));try{if(list.length)await Capacitor.Plugins.LocalNotifications.schedule({notifications:list.slice(0,50)})}catch(e){console.warn('Não foi possível agendar lembretes',e)}}
function hashId(s){let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return Math.abs(h)||1}
$('#quickSettings').onclick=()=>go('settings');$('#fab').onclick=()=>{let defaults={workout:'workout-session',food:'supplement',finance:'expense',college:'note',shopping:'shop:month',cats:'catcare',health:'appointment',therapy:'therapy-session',tasks:'task',books:'book'};if(defaults[current])addByKey(defaults[current]);else showMore()};
nav();render();
if('serviceWorker'in navigator && location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
